// Ported from the Node app's Sequelize model DocumentTemplate (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class DocumentTemplateConfiguration : IEntityTypeConfiguration<DocumentTemplate>
{
    public void Configure(EntityTypeBuilder<DocumentTemplate> builder)
    {
        builder.ToTable("document_templates", t =>
        {
            t.HasCheckConstraint("CK_document_templates_type", "[type] IN (N'bonafide', N'transfer', N'character', N'fee')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Type).HasColumnName("type").HasColumnType("nvarchar(20)").IsRequired();
        builder.Property(e => e.Body).HasColumnName("body").HasColumnType("nvarchar(max)").IsRequired();
        builder.Property(e => e.UpdatedByName).HasColumnName("updated_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.HasIndex(e => e.Type).IsUnique();
    }
}
